                    (13, "body", "poure wyne throughe the bag diu[er]s tymes and drinke itt.", "pour wine through the bag divers times, and drink it.", ""),
                    (14, "heading", "To oppen water", "To open [void] water", ""),
                    (15, "body", "℞ wormwood l[ibra] ß. steepe it in white wyne on[e] nyghte: in the next", "Take 1/2 lb wormwood, steep it in white wine one night; the next", ""),
                    (16, "body", "morning Boile away on[e] third parte. Drinke of this wyne warme and", "morning boil away one third part. Drink of this wine warm and", ""),
                    (17, "body", "treakle apon it.", "treacle upon it.", ""),
                    (18, "body", "℞ Pare turneppes & shred them then Boile them in water & drinke the water. better w[i]t[h] wyne.", "Take pared turnips and shred them, then boil them in water and drink the water; better with wine.", ""),
                    (19, "heading", "An Experim[en]t for y[e] Dropsie", "An experiment for the dropsy", ""),
                    (20, "body", "℞ of the fatt of a gelded dogge y[e] quantitie of a walnut melt git and drinke it", "Take of the fat of a gelded dog the quantity of a walnut, melt it and drink it", ""),
                    (21, "body", "in a drafte of warme Beare: Bast his meate & dresse it w[i]t[h] the", "in a draught of warm beer; baste his meat and dress it with the", ""),
                    (22, "body", "same fatt the more the Better. And this is good for the yelow Jaundies.", "same fat, the more the better. And this is good for the yellow jaundice.", ""),
                    (23, "heading", "for the Jaundis Dropsie", "For the jaundice dropsy", ""),
                    (24, "body", "℞ greate Earth wormes mak them into pouder & drink therof w[i]t[h] the destilled water of onyons.", "Take great earthworms, make them into powder, and drink thereof with the distilled water of onions.", ""),
                    (25, "heading", "ffor the Dropsie", "For the dropsy", ""),
                    (26, "body", "Boile pigeon Dunge in p[ar]sley or fennell water & straine washe y[e] Swelnd legge & w[i]t[h] lynen cl[oth] & stoue in the liquor and into the Towles &c.", "Boil pigeon dung in parsley or fennel water, strain, wash the swelled leg with a linen cloth, and foment in the liquor.", ""),
